from pathlib import Path
root=Path.cwd(); old=root/'build/t473-s11/current-return-attribution-v2'; dest=root/'build/t473-s11/current-return-identity'; dest.mkdir(exist_ok=True)
helper='''\n#include <stdio.h>\nstatic void audit_identity_trace(const char *stage, HWND window, DWORD status) {\n char path[MAX_PATH], line[160]; DWORD saved=GetLastError(), n, written, size; HANDLE f;\n n=GetEnvironmentVariableA("MVDM_WOW_WINDOW_TRACE_PATH",path,sizeof(path));\n if(n && n<sizeof(path)) { f=CreateFileA(path,FILE_APPEND_DATA,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);\n if(f!=INVALID_HANDLE_VALUE) { size=(DWORD)sprintf_s(line,sizeof(line),"%lu IdentityFailure tid=%lu stage=%s hwnd=%08lX status=%lu\\r\\n",GetCurrentProcessId(),GetCurrentThreadId(),stage,(DWORD)(ULONG_PTR)window,status); if(size) (void)WriteFile(f,line,size,&written,NULL); CloseHandle(f); } }\n SetLastError(saved);\n}\n'''
for filename, needle,repl in [
('wow_user_object_bindings.c','''        if (!capture_window(roots[i], &captured) ||\n                !put_observation(&rows, &count, &capacity, index, &captured)) goto done;''','''        if (!capture_window(roots[i], &captured)) { audit_identity_trace("required-root-capture", roots[i], GetLastError()); goto done; }\n        if (!put_observation(&rows, &count, &capacity, index, &captured)) goto done;'''),
('wow_menu_client_bindings.c','''        if (!GetWindowInfo(window, &info)) return FALSE;''','''        if (!GetWindowInfo(window, &info)) { audit_identity_trace("menu-owner-info", window, GetLastError()); return FALSE; }''')]:
 s=(root/'src/wow32-dll/source'/filename).read_text(); assert s.count(needle)==1,(filename,s.count(needle)); pos=s.index('\n',s.index('#include'))+1; s=s[:pos]+helper+s[pos:]; (dest/filename).write_text(s.replace(needle,repl))
 src=(old/'compile.cmd').read_text(); src=src.replace('current-return-attribution-v2\\wow_user_task_lifecycle.obj','current-return-identity\\'+filename.replace('.c','.obj')).replace('current-return-attribution-v2/wow_user_task_lifecycle.c','current-return-identity/'+filename).replace('/O2 /Fo','/I "O:/repos.hobby/ntvdm64/src/wow32-dll/source" /O2 /Fo'); (dest/('compile-'+filename+'.cmd')).write_text(src)
link=(old/'link.cmd').read_text().replace('current-return-attribution-v2/wow32','current-return-identity/wow32').replace('obj/wow32-dll/wow_user_object_bindings.obj','O:/repos.hobby/ntvdm64/build/t473-s11/current-return-identity/wow_user_object_bindings.obj').replace('obj/wow32-dll/wow_menu_client_bindings.obj','O:/repos.hobby/ntvdm64/build/t473-s11/current-return-identity/wow_menu_client_bindings.obj')
(dest/'link.cmd').write_text(link)
print('Prepared test-only exact root and menu owner tracing; lifecycle object remains prior diagnostic.')
